package com.splitter.meta;

import java.lang.annotation.Documented;
import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * Marks code that was generated by an AI tool.
 *
 * <p>{@code tool} and {@code prompt} are filled in when the code is generated.
 * {@code refinedBy} and {@code changes} are filled in by a human when the code is later edited.
 */
@Documented
@Retention(RetentionPolicy.RUNTIME)
@Target({ElementType.TYPE, ElementType.METHOD, ElementType.CONSTRUCTOR})
public @interface AIGenerated {

    /** The AI tool that generated the code, e.g. "Claude Code". */
    String tool();

    /** The prompt id, as recorded in docs/AI_USAGE_LOG.md. */
    String prompt();

    /** Name of the human who refined the code; empty if not refined yet. */
    String refinedBy() default "";

    /** Short description of the human changes; empty if not refined yet. */
    String changes() default "";
}
